entries[9492] = { ["name"] = "Zerfetzen", ["text"] = "30 Energie Nahkampfreichweite\nSofort\nBenötigt Katzengestalt\nFinishing-Move, der Schaden im Lauf der Zeit verursacht. Der Schaden erhöht sich pro Combopunkt sowie durch Eure Angriffskraft:\n1 Punkt: [(4 + 7 * 1 + 0.01 * Attack power) * 6 ] Schaden im Verlauf von 12 sec.\n2 Punkte: [(4 + 7 * 2 + 0.02 * Attack power) * 6 ] Schaden im Verlauf von 12 sec.\n3 Punkte: [(4 + 7 * 3 + 0.03 * Attack power) * 6 ] Schaden im Verlauf von 12 sec.\n4 Punkte: [(4 + 7 * 4 + 0.04 * Attack power) * 6 ] Schaden im Verlauf von 12 sec.\n5 Punkte: [(4 + 7 * 5 + 0.05 * Attack power) * 6 ] Schaden im Verlauf von 12 sec." }
entries[9493] = { ["name"] = "Zerfetzen", ["text"] = "30 Energie Nahkampfreichweite\nSofort\nBenötigt Katzengestalt\nFinishing-Move, der Schaden im Lauf der Zeit verursacht. Der Schaden erhöht sich pro Combopunkt sowie durch Eure Angriffskraft:\n1 Punkt: [(6 + 9 * 1 + 0.01 * Attack power) * 6 ] Schaden im Verlauf von 12 sec.\n2 Punkte: [(6 + 9 * 2 + 0.02 * Attack power) * 6 ] Schaden im Verlauf von 12 sec.\n3 Punkte: [(6 + 9 * 3 + 0.03 * Attack power) * 6 ] Schaden im Verlauf von 12 sec.\n4 Punkte: [(6 + 9 * 4 + 0.04 * Attack power) * 6 ] Schaden im Verlauf von 12 sec.\n5 Punkte: [(6 + 9 * 5 + 0.05 * Attack power) * 6 ] Schaden im Verlauf von 12 sec." }
